def parse(s):
    t=list(map(int,s.split()))
    n=t[0]
    if n!=len(t)-1:
        return None
    if n<1 or n>8:
        return None
    for x in t[1:]:
        if x<0 or x>5:
            return None
    return {'n':n,'a':t[1:]}

def render(c):
    return str(c['n'])+' '+chr(10)+' '.join(map(str,c['a']))

def valid(c):
    if c is None:
        return False
    n=c['n']
    if n<1 or n>8:
        return False
    for x in c['a']:
        if x<0 or x>5:
            return False
    return True

def solve(s):
    c=parse(s)
    if c is None:
        return '0'
    return str(len(set(c['a'])))

def generate(seed,index,mode):
    if mode=='random':
        import random
        rng=random.Random(seed+index)
        n=rng.randint(1,8)
        a=[]
        for _ in range(n):
            a.append(rng.randint(0,5))
        return {'n':n,'a':a}
    elif mode=='adversarial':
        cases=[]
        for n in range(1,9):
            for base in range(6):
                a=[base]*n
                cases.append({'n':n,'a':a})
        return cases[index%len(cases)]
    else:
        cases=[]
        for n in range(1,9):
            for base in range(6):
                a=[base]*n
                cases.append({'n':n,'a':a})
        return cases[index%len(cases)]

def shrink(c):
    cases=[]
    n=c['n']
    a=c['a']
    if n>1:
        cases.append({'n':n-1,'a':a[:-1]})
        cases.append({'n':n-1,'a':a[:n-1]})
    if len(a)>1:
        cases.append({'n':n,'a':a[:-1]})
        cases.append({'n':n,'a':a[:len(a)-1]})
    if n>1 and len(a)>1:
        cases.append({'n':n-1,'a':a[:-1]})
    return cases[:16]

