def valid_input(stdin):
    try:
        tokens = stdin.split()
        if len(tokens) < 1:
            return False
        n = int(tokens[0])
        if not (1 <= n <= 8):
            return False
        if len(tokens) != n + 1:
            return False
        a = []
        for i in range(1, n + 1):
            val = int(tokens[i])
            if not (0 <= val <= 5):
                return False
            a.append(val)
        return True
    except:
        return False

def solve(stdin):
    tokens = stdin.split()
    if not valid_input(stdin):
        return "0"
    n = int(tokens[0])
    a = []
    for i in range(1, n + 1):
        a.append(int(tokens[i]))
    return str(len(set(a)))
